package com.bank.stream.service;

import com.bank.stream.model.TxnEvent;
import java.util.LinkedHashMap;
import java.util.Map;

// Simulates the incremental result table of a groupBy("accountId").count().
// In real Structured Streaming, Spark maintains this state for you.
public class IncrementalCounter {

    private final Map<String, Long> counts = new LinkedHashMap<>();

    // Process one micro-batch of new rows and update the running result.
    public Map<String, Long> processMicroBatch(java.util.List<TxnEvent> batch) {
        for (TxnEvent e : batch) {
            counts.merge(e.getAccountId(), 1L, Long::sum);
        }
        return new LinkedHashMap<>(counts); // snapshot of the result table
    }
}
