package com.bank.stream;

import com.bank.stream.model.TxnEvent;
import com.bank.stream.service.IncrementalCounter;
import java.math.BigDecimal;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: simulate the unbounded-table, micro-batch model.
public class StructuredStreamingDemo {

    private static final Logger log = Logger.getLogger(StructuredStreamingDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                        new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        IncrementalCounter counter = new IncrementalCounter();

        // Two simulated micro-batches of new rows arriving on the stream.
        List<TxnEvent> batch1 = List.of(
            new TxnEvent("SAV2001", new BigDecimal("50000")),
            new TxnEvent("CUR3001", new BigDecimal("12000")),
            new TxnEvent("SAV2001", new BigDecimal("3000")));
        List<TxnEvent> batch2 = List.of(
            new TxnEvent("SAV2001", new BigDecimal("700")),
            new TxnEvent("CUR3001", new BigDecimal("9000")));

        log.info("Micro-batch 1 arrives (readStream → incremental query)");
        var r1 = counter.processMicroBatch(batch1);
        log.info(() -> "Result table after batch 1: " + r1);

        log.info("Micro-batch 2 arrives (same query runs incrementally)");
        var r2 = counter.processMicroBatch(batch2);
        log.info(() -> "Result table after batch 2: " + r2);

        log.info("Structured Streaming unbounded-table simulation complete.");
    }
}
